INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('73f4a6d0-77c3-4fcf-8496-932efd382d2a','e2fd2121-0282-45c8-93d8-0723b8a14b8c',NULL,'天使猪猪乐','other','张导的店特殊会员问题','为什么张导的店小程序有些东西需要特定会员购买，之前有c2000max原装拆机壳购买不了，而群里有些人就能购买。c2000max内测用户好久没关注过这方面了，只知道以前都是在鹏友go小程序上购买产品','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User raises a concrete product purchase/access issue regarding membership restrictions and inconsistent availability, which is valid feedback.',1788787356094,'2026-09-03',1788604231724,'2026-09-03',1788604231724,1788604231724,1789125296648,NULL,1,0,NULL,'not_selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('1b9ead85-dfcc-4412-8f8f-6a0045d2ee7d','92d64ce6-ba77-4a4b-b060-30462d38a452',NULL,'天使猪猪乐','other','c2000max bug反馈问题','c2000max反馈bug不方便，以前群里有发过反馈bug的链接，提交过一次之后遇到bug再想反馈的时候并不会刷新链接还是会显示以前填过的内容，而且后来这条链接也找不到了，现在想反馈问题就只能去微信联系个人反馈了，感觉十分不方便，希望能在web端后台或者app后台加一个反馈bug的窗口。另外每次更新只能在网盘或者群里查看更新日志以及系统包，这样也十分不方便，建议在后台加上历史更新日志（包含每个版本更新了什么内容修复了什么问题），如果能再提供一个历史版本下载按钮或者窗口就更好了，这样照顾不同群体的客户，用鲲鹏产品的人不一定每个都进群了也不定每个人都知道鲲鹏网盘地址。','unprocessed',NULL,NULL,0,'filtered','manual',NULL,'manual_filter',1789038753219,'2026-09-03',1788604745650,'2026-09-03',1788604745650,1788604745650,1789038753219,NULL,0,0,NULL,'pending');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('f6cec3ee-fb51-47a3-a6f8-0810e583cc94','b4321ed8-be19-4c11-bf48-fd6eec70526c',NULL,'天使猪猪乐','other','继上一条反馈问题','如果app和网页端只能二选一的话，个人更希望那些功能加在web端后台（技术上如果能实现的话），因为app也不是每个人都会去下载，但是网页端是每个用户都会登进去访问的','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User gives a concrete product suggestion about where to add features (web backend vs app), with reasoning, which is useful feedback.',1788605194824,'2026-09-03',1788605193935,'2026-09-03',1788605193935,1788605193935,1789127312624,NULL,0,0,NULL,'selected');
