INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('43a194e6-b0c4-4531-b388-c2f0ee81061a','a2d57b77-3299-43be-84e7-c5a6115897a9',NULL,'兔玖号','released_hardware',NULL,'AK 68－798，我系统里面什么时候出个皮肤啊？我是尊贵的798用户啊。竟然还是白皮。还有就是798磁吸外壳，张导能不能免费发我？不要正面的，只要背面的，上螺丝那一块也行，我自己安。','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User provides concrete product feedback about missing UI skin and accessory request for specific hardware model.',1788787415925,'2026-09-03',1788652227280,'2026-09-03',1788652227280,1788652227280,1789127312632,NULL,1,0,NULL,'not_selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('f114d673-f74c-4fab-9960-756f0b79f49d','e5f143e6-6f41-4334-9621-135b637482ec',NULL,'说我就噜噜脸','unreleased_product',NULL,'上次直播提到ak08，说上预售到现在也没上，也没公布价格，冒昧问一下进度如何了导','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Customer asks about the release/progress of product ak08 and notes pre-sale/price information is missing; this is a valid product inquiry/complaint.',1788675146776,'2026-09-03',1788675145719,'2026-09-03',1788675145719,1788675145719,1789119882017,NULL,0,0,NULL,'selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('e327540a-8cc4-447e-bc7d-446fd1f1a059','c2625b70-94d4-4279-9471-ea6fbde7d298',NULL,'老樊','other','游戏延迟','张导，max的游戏延迟还是稍微有点高，我之前使用过烽火的air和pro2代，在相同的位置下，烽火的产品游戏延迟要比max低个差不多10ms，而且游戏延迟波动也有点高，能差不多有5到8ms，我认为这不是硬件方面的问题，这应该是固件优化方面的，愿意入手max的基本上都是年轻人，喜欢玩些竞技类的游戏，对游戏延迟和波动还是比较在意的。在好点的基站下max的延迟确实能干到20ms以内，但是友商的产品也能做到，在不那么优秀的基站和信号下把游戏延迟和波动干低那才是真的牛逼，并不是所有用户周围的信号都很优秀，我认为一个优秀的产品不是仅仅是靠产品堆料给推上去的，后面的软件优化和使用体验才是最重要的，去年我也用过中兴的u60，这款产品的堆料确实很足，但他的软件优化真的是一言难尽，导，我作为m鲲鹏产品的用户，希望鲲鹏越来越好，也希望自己手里的max越来越完美。','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Contains a concrete product issue (game latency/fluctuation) with comparisons and a suggestion for firmware optimization.',1788693277125,'2026-09-03',1788693276109,'2026-09-03',1788693276109,1788693276109,1789125073870,NULL,0,0,NULL,'selected');
