INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('b1463d15-731c-4b6c-9b08-d9bf9e5bde93','d80a7d39-e0fe-4e15-a738-a0e0d3a97fc0',NULL,'1','other','关于群里探讨割包皮','该群内多人公开讨论割包皮这类私密生殖相关话题，内容涉及个人生殖器官，在公开群聊展开此类讨论，观感不适，希望张导进行管理点评，规范群内聊天氛围。','unprocessed',NULL,NULL,0,'filtered','manual',NULL,'manual_filter',1789040009216,'2026-09-03',1788773723080,'2026-09-03',1788773723080,1788773723080,1789040009216,NULL,0,0,NULL,'pending');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('ba86fff2-330c-4085-aee2-168b8e335789','82c8e258-e035-4205-b40a-32be10d0e59c',NULL,'FallaxAura','unreleased_product',NULL,replace('导，快点推出无界卡吧，我快被这个校园网折磨死了，一个人限速2.5MB/s这用个蛋的Wi-Fi啊😠\n我自己都快被折磨疯了，并且已经有好几个同学给我抱怨过这个事情了','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User complains about campus network speed limits and requests an unreleased product, which is concrete product feedback.',1788787415483,'2026-09-03',1788773877603,'2026-09-03',1788773877603,1788773877603,1789124300937,NULL,1,0,NULL,'selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('a8065806-7172-4c60-82ea-db653f0b1290','c30503da-3318-4d8a-a0d6-54f9970cd869',NULL,'🐴到成功','unreleased_product',NULL,'AK08天线大概什么时候可以购买，现在我真的非常需要这个天线，我们校区今年多招收了559个人，导致这几天网速哐哐往下掉，无论白天还是晚上网速都拉不起来，就连天火卡也只有100兆的网速，之前移动卡都是260兆的网速，联通卡由原来的400兆掉到190兆，最主要的是无论哪个运营商的基站，玩网游时不时抽风，延迟突然飚到700毫秒，有了AK08天线我打算不用宿舍楼内的RRU了，直接用AK08天线对准远处校外的基站，校外的基站支持5G-A和三载波，请张导给个大概的时间，以平复我焦急等待的心，🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Genuine product availability inquiry with specific technical need and network performance issue details.',1788783001854,'2026-09-03',1788782998891,'2026-09-03',1788782998891,1788782998891,1789125008176,NULL,0,0,NULL,'selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('7bc02f7a-b7bd-4fcf-9cc6-997168d27c53','693a0b4b-6baa-40fe-ba8e-1a46858d883d',NULL,'Jz','released_software',NULL,replace('张导张导，认真反馈一个我觉得很重要也必须解决的问题——鲲鹏无限现在的Web后台和APP在整体产品质感尤其是视觉设计上还有很大的提升空间。\n\n我觉得鲲鹏做CPE最有潜力的一点，就是鲲鹏不只是一个简简单单的组装厂，把一堆的模组装进一个盒子里然后卖给用户，而是能把硬件性能，外观设计和系统体验等等汇聚成一个成熟而完美的产品体验。\n\n现在AI辅助开发已经非常成熟，前端实现的门槛快速降低，我觉得鲲鹏非常应该把审美、交互、细节重视起来，比方说Web和APP后台的信息层级、状态展示、图表等等，都应该认真的优化。\n\n我甚至有个很强烈的想法——鲲鹏应该成为，也完全可以成为CPE界的Apple。参数信号好这是基础，还要让用户第一次打开包装第一次看到设备第一次进入后台的时候，都能感觉到这个东西做得太美丽了。\n\n我自己是数据科学专业的学生，也一直在学习和使用AI、编程以及各种开发工具，对产品设计和前端也特别感兴趣，看到鲲鹏现在的软件界面，我是真的很想自己动手重新设计一套哈哈哈哈哈。\n\n如果鲲鹏愿意着手做UI改版和前端设计优化，我特别希望能参与进去，哪怕先让我做一个页面原型、改版Demo，或者帮忙提一整套交互和视觉方案都可以。\n\n我是真的挺希望看到鲲鹏把硬件、工业设计和软件体验全部做到同一个水准的。期待有一天“CPE界的Apple”真的就是鲲鹏。\n\n张导加油，鲲鹏加油！','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Detailed product/UI improvement suggestion with concrete issues and willingness to contribute; not abusive or meaningless.',1788792009185,'2026-09-05',1788792006107,'2026-09-05',1788792006107,1788792006107,1789251245217,NULL,1,0,NULL,'selected');
