INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('0082aa23-d5b0-4737-9d7f-f9cb03642e9a','487edc80-7fb8-4106-801d-08416555e756',NULL,'五圈','unreleased_product',NULL,'我是c2000内测和c8-688公测用户，我想要一张无疆卡张导','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User identifies as beta tester and requests a specific perk (card), which is a concrete customer request related to the product program.',1788798280502,'2026-09-05',1788798277733,'2026-09-05',1788798277733,1788798277733,1789124492855,NULL,1,0,NULL,'not_selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('e6367913-99a1-4945-b374-327d3917307c','5ecaf706-96a4-464d-a883-43585cb671cc',NULL,'团','other','希望增加便携款无模块设备的产品',replace('张导你好，我大学的时候就接触到这类产品，当时生活费有限，一直是自己DIY玩，也因此了解到了鲲鹏和张导。\n深入了解后特别认可鲲鹏这个年轻品牌的产品，一直想入手官方的设备，但我自己已经有模块了，就想买无模块的空机。\n咱们现在有AK68的无模块版我知道，但它定位比较极致，像我这种普通市区用的用户其实用不上这么高的规格。\n特别希望张导能考虑上架C8-788这类更便携的无模块版本，给我们已有模块的玩家多一个亲民便携的选择。\n感谢张导能看到这里！','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Concrete product suggestion requesting a portable module-free version; meaningful feedback.',1788801815543,'2026-09-05',1788801771499,'2026-09-05',1788801771499,1788801771499,1789122246675,NULL,1,0,NULL,'selected');
