INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('25b6a161-c758-405e-8ebf-d622250a3991','21615f92-2110-4bc6-ae3d-fc2a985eb6d3',NULL,'无泪的遗憾','released_software',NULL,'搜索信号频段，手机能稳稳的直连住B3,c2000max一直不断的切频，独特的锁B1。我设备的是联通内置卡，我手机也是联通，网联网卡也是联通，别人家的移动流量这设备用不了，求一张移动流量卡，这边联通基站不如别人家的，不然真的用起来体验很拉垮，三倍F50价格的设备，用起来不如F50。我以前用F50的时候从来不会有这种死锁B1，手机能链接B3频道，而C2000max却不行，用起来体验很拉垮','unprocessed',NULL,NULL,0,'filtered','manual',NULL,'manual_filter',1789039364003,'2026-09-05',1788829234905,'2026-09-05',1788829234905,1788829234905,1789039364003,NULL,1,0,NULL,'pending');
