INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('4bb27e00-ee97-4cb3-8471-9ed9d05b7571','b2993c60-8563-4eb3-a9d8-e2ea4541a9cd',NULL,'额','other','售前售后问题。',replace('第一每次发售的产品或者过后的产品，问客服一问三不知，比如说ak68，铝合金max，接受信号更好了但是它的无线网覆盖范围多大不知道？我就有个疑问自己家做出来产品没有经过测试或者实验吗？我买了二个max，我想升级个铝合金壳，我问的一关于产品上问题，问了以后过了好几天才回复我？\n打个比方我如果做产品我会做各种现实测试大量的测试假如顾客有疑问我会快速的解答，比如说在max信号不好的地方换成铝合金Max网速对比散热对比恶劣天气对比，无线网覆盖对比max和铝合金max，在一个多少平方的房子里几室一厅测网速对比信号覆盖对比，要对比肯定是以升级上的项目逐一对比。\n二：每次直播搞的就跟发布会一样，叽里咕噜的说一些有的没的，我们是顾客，不是学生更不是同行交流，你可以在你的粉丝群搞个ppt来发一下你的产品详细的ppt这样谁想更多了解就多了解，而不是每次叽里咕噜的讲一堆，我们在直播哪里始终得不到自己想要得到的东西就陪着你直播，张导我们都是有时间的，有在工作的，有在上学的，有在看孩子的，每次的直播先搞个直播简介1-9话题，然后再做个本次直播的ppt发到粉丝群里，然后根据热爱这一个方面的单独可以开个专场交流直播，我每一次咨询给我的感觉就是一传二、二传三、三传四、然后再4传三，三传二，二传一的才能回答我。','\n',char(10)),'unprocessed',NULL,NULL,0,'filtered','manual',NULL,'manual_filter',1789039184811,'2026-09-05',1788832136748,'2026-09-05',1788832136748,1788832136748,1789039184811,NULL,1,0,NULL,'pending');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('500eb178-e5d2-4801-a4d8-947522e0f3f9','51eb6e8e-dfc5-440e-8d5e-fee69e44f1ed',NULL,'无名先生🚬','unreleased_product',NULL,'张导，新产品可以增加NFC碰一碰连接功能嘛','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Suggestion for a new product feature (NFC tap-to-connect), which is meaningful product feedback.',1788832579818,'2026-09-05',1788832577002,'2026-09-05',1788832577002,1788832577002,1789119548377,NULL,1,0,NULL,'selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('f5520ed8-de03-49f5-b662-190680e24a86','61df610d-f00f-4bb9-8eeb-aec82d37aeb2',NULL,'功夫熊猫','other','关于加强高阶会员服务与保障公司权益的若干建议',replace('1.建议张导可以适当向高阶会员（虚空长老）征收会员费，收费制可以筛选优质会员和剔除部分浑水摸鱼的黑粉，并增加黑粉抹黑公司形象的成本。\n2.在增收会员费的同时增加高阶会员的权益（强烈建议高阶会员实名制）使用户粘性近一步增强。比如会员可以享受成本价维修设备，高端设备延保，专属客服，优先体验新品，设备维修保养期间可以享受备用机器服务，特殊情况租赁高端机器服务等。（注：收取会员费必须实名登记并签署合同签字，自愿参加！）\n3.详细分析一下设备维保期间享受备用机器服务：比如会员费为一年二百元，可以在老旧设备售后工单成立以后，给用户寄一台DD/CC/TT之类的低于售价但高于成本价的设备以保障用户的基础用网需求，可以在设备外壳印好备用服务机器等字样，并加设云控防止用户拿走不归还的情况发生。（注：1.会员费建议设置固定时间缴纳，防止一些人因为一些需求来临时抱佛脚。2.只提供设备，不提供卡。3.备用机服务建议收押金，比如DD类收一百，C2000pro收三百，不建议提供高端设备）\n4.详细分析一下特殊情况租赁高端设备：比如C2000ultra/C8-788/C5800/AK68/NBCPE系列，会员临时租赁高端设备必须收足量押金或者开通支付宝免押金相关业务等，保障公司资产安全。可以按照设备折旧率的相关公式计算租金，比如7天/15天/30天/以租代买/等方式。建议也加设云控防止用户白嫖。','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Concrete suggestions on membership fees, benefits, and asset protection; meaningful product/service feedback.',1788833256346,'2026-09-05',1788833178417,'2026-09-05',1788833178417,1788833178417,1789127322592,NULL,2,0,NULL,'not_selected');
