INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('674c6f97-69f6-46d2-9426-1d7df404c496','66064c87-df3a-4142-9ad2-7846a7163b07',NULL,'涞落（吃丹修仙）','other','散热问题','铝合金版本使用有一阵了，唯一问题还是发热问题，平平常常四五十度，也不知道属于正常温度不，不过我是放在车里用，东北这会还好估计夏天在车里温度会更高，正好闲置一个手机散热器，给利用上，正好解决了高温的问题，基本温度能保持三十多度，废物利用解决大问题，感觉推广一下可以😊','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User reports a concrete heat issue with the aluminum version and describes usage context and a workaround, which is useful product feedback.',1788853454266,'2026-09-05',1788853450872,'2026-09-05',1788853450872,1788853450872,1788965534074,NULL,1,0,NULL,'pending');
