INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('68596891-37e0-44b8-a6c1-5243921f04b3','6759cd21-e882-44d0-b596-d106a93093f0',NULL,'虚伪','released_software',NULL,replace('@鲲鹏张导 \n1.更新后显示内置卡，短信功能无法使用，实际上是插了外置卡，已做过切卡，重启，软件卸载重装等操作，无效果\n2.主页页签排布不合理，本来app也没优化到很好用的地步，还把云端登录后台入口折叠到更多里面，增加繁琐操作，完全可以做3*3，为什么要做2*3，完全可以跟之前一样做左右滑动页签，很明显软件部门的人员就没用过几次app，开发人员自己都不熟悉自家的软件怎么去做更好的优化？','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Concrete bug report and UI/UX complaints with specific details; valid product feedback.',1788922393408,'2026-09-05',1788922388272,'2026-09-05',1788922388272,1788922388272,1789127380137,NULL,1,0,NULL,'not_selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('1cbc6262-ee9f-4dba-8c25-2b567e8d11c4','911c9444-3e02-4211-995a-b17aa9f6fcd9',NULL,'小林同学','other','关于流量共享的主题。和禁区地方为老家的设备使用情况',replace('张导您好，两点真实用户建议：\n1、本人老家，在禁区，担心天火卡去到老家广西(陆川)会直接断网，还存在锁设备和卡的风险。希望至少增加提前预警提示，不要抵达当地之后才出现异常。同时只有单一设备C2000MAX 目前只使用一张卡的情况下，回家根本没办法使用设备，相当于断网的节奏。如果继续开通内置卡流量，费用就会产生较高。\n2、希望推出流量共享卡，1主卡+2张子分身卡，合计3个终端共用同一流量池。分别供家里网络使用、车载CPE独立使用，后台能看各卡流量消耗、可远程开关子卡，控制分身卡。这套方案可以降低使用成本，一个账号充值，三个账号共用流量池。达到减少费用的情况，\n3总需求是可以有一张在禁区广西内使用，并且可以支持流量共享池分身子母卡','\n',char(10)),'unprocessed',NULL,NULL,0,'filtered','manual',NULL,'manual_filter',1789039792522,'2026-09-05',1788922392952,'2026-09-05',1788922392952,1788922392952,1789039792522,NULL,1,0,NULL,'pending');
