INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('60725963-398e-4bff-a53c-7ea55165f497','c39a0944-564c-42b7-b539-f43463314464',NULL,'WBaKn','released_software',NULL,'c2000max后台能不能更新屏蔽小区的功能，同样是n41频段，一个信号较好但是不能载波聚合，一个信号稍弱一点但是可以载波聚合，网速更快，但是CPE经常自动连上那个无载波聚合的基站，且锁小区后就无法载波聚合了。希望增加屏蔽小区的功能让CPE自动连上那个可以载波聚合的基站','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Concrete product feature request and technical complaint about CPE cell locking and carrier aggregation behavior.',1788945120340,'2026-09-05',1788945117590,'2026-09-05',1788945117590,1788945117590,1789127551070,NULL,1,0,'18902561447','selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('86bdb8b9-6812-40dc-881b-ac8d1cb079eb','f3fcc7a5-025d-4ecf-8263-14fb5591a199',NULL,'毒刺','other','我与鲲鹏风雨同舟',replace('始于体验，忠于匠心｜我的鲲鹏C2000MAX、NB CPE全程成长之旅\n \n从年前有幸参与鲲鹏C2000MAX公测开始，我便与鲲鹏设备结下了不解之缘。这段一路走来的使用历程，不只是一台上网设备的更迭升级，更是我亲眼见证品牌用心打磨产品、真诚对待用户、极致深耕服务的全过程。\n \n最初，我以公测用户的身份率先体验鲲鹏C2000MAX。带着好奇与期待深度实测使用，感受着新品的性能优势，同时也如实反馈使用中的细节问题。体验过后，出于对产品实力的认可，我果断入手了鲲鹏NB CPE设备，一步步深耕5G无线设备的使用与实测，沉浸式感受品牌的产品实力。\n \n为了追求更极致的网络体验，我不断搭配专属配件优化设备。从升级铝合金散热壳体、外置高增益天线，大幅提升设备散热效率与信号接收稳定性，解决了传统设备高温降频、信号偏弱的痛点；再到搭配天火流量卡，适配全网频段、优化网络速率，解锁了更流畅、低延迟的上网体验。每一次硬件升级，都是为了贴合真实使用场景，追求稳定高效的网络体验。\n \n而最让我惊喜与动容的，从来不止是产品的硬件实力，更是鲲鹏以人为本的温度与态度。使用过程中，难免会有体验不佳、心绪烦躁的时刻，张导始终耐心倾听、温柔劝导，细心解答我的所有疑问，安抚负面情绪，让冰冷的数码设备，多了一份难得的真诚与温暖。\n \n不同于多数品牌忽视用户反馈、迭代敷衍的现状，鲲鹏始终把用户体验放在首位。对于我以及众多用户提出的每一条建议、每一处问题反馈，官方都做到及时接收、快速响应、落地整改，从不敷衍搪塞。一次次软件迭代更新，一次次功能细节优化，从后台系统流畅度、频段适配优化，到使用细节、功能适配的打磨，始终精益求精。\n \n从最初的公测样机，到成熟的量产设备，从硬件配件的不断完善，再到如今专属UV个性定制壳体的上线，鲲鹏一直在突破自我、持续精进。硬件上不断打磨工艺、升级配置，力求把产品硬件做到极致；软件上持续迭代优化、修复短板，力求把系统体验做到极致；服务上真诚相待、耐心负责，力求把用户服务做到极致。\n \n一路走来，我亲眼见证一台设备从青涩到成熟，一个品牌从用心到深耕。不辜负每一份用户信任，不忽视每一处细节瑕疵，不敷衍每一次体验反馈。以匠心打磨产品，以真心守护用户，以极致诠释专业，这便是鲲鹏最动人的底气，也是我一路追随、始终认可的根本原因。','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','manual',NULL,'manual_restore',1789036029162,'2026-09-05',1788950851018,'2026-09-05',1788950851018,1788950851018,1789250832347,NULL,1,0,'15295007172','selected');
