INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('573e0197-f80f-46c1-8048-fb7ce89d400b','d575d351-5a62-4942-a79a-5bdcfca03a35',NULL,'芭芭鸭鸭','unreleased_product',NULL,'近海测试本人真实船员三副＋渤海湾到长江口＋单航次航行3~4天锚泊2到15天 希望参与鲲鹏炮测试名额 为了网络焦头烂额 关注鲲鹏炮很久了一直没有出 希望能参与测试同时也希望能是最早一批购买者  测试结束后愿意邮寄回设备  希望张导考虑一下我','unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','User expresses strong interest in unreleased product and requests test participation, reflecting product demand and user experience context.',1789208359945,'2026-09-05',1789208357761,'2026-09-05',1789208357761,1789208357761,1789223571029,NULL,1,0,NULL,'selected');
INSERT INTO "feedback" ("id","submission_key","user_id","douyin_nickname","topic","custom_topic","content","internal_status","reply_type","reply_content","is_todo","moderation_status","moderation_source","moderation_category","moderation_reason","moderated_at","privacy_policy_version","privacy_agreed_at","livestream_policy_version","livestream_agreed_at","created_at","updated_at","moderation_attempt_token","moderation_attempts","moderation_next_retry_at","shop_phone","routing_status") VALUES('4c243e3b-e67e-4700-ab40-0fbebba31318','93254d32-81b7-45ca-a65d-aea3e497b311',NULL,'锦禧褔食品（揭阳）','other','建议',replace('鲲鹏未来发展展望\n1，坚持发展个性化diycpe美化工艺争取破圈\n​2.研究竞品某cpe游戏延迟，持续优化鲲鹏设备的游戏延迟，降低延迟，超过友商或者和友商齐平\n​3 软件持续优化聚合方面的bug，打通目前现有产品聚合便利性，既然鹏友要玩官方就出手优化\n​4.针对大众市场需求推出相应的产品，鲲鹏要赚钱别不好意思，随身WiFi什么的通通推陈出新，鲲鹏需要的是培养各种需要物联网上网的潜在鲲鹏用户，在鲲鹏这里既可以傻瓜式的上网也可以根据自己的喜好玩机\n​5.流量卡优化与运营商的合作，机卡绑定，让消费者只要入手鲲鹏设备就不为后续流量上网而担忧\n6，优化鲲鹏二手商城回收机制，让购买鲲鹏产品的鹏友没有后顾之忧，推出更明白易懂的置换政策\n7.时不时户外直播，毕竟办公室直播久了也会视觉疲劳\n\n还有很多很多的想法，这是我作为10+12级老粉的建议和想法，希望鲲鹏越来越好\n​','\n',char(10)),'unprocessed',NULL,NULL,0,'kept','ai','valid_feedback','Detailed product and business suggestions from a long-time user, clearly valid feedback.',1789213138565,'2026-09-05',1789213135738,'2026-09-05',1789213135738,1789213135738,1789223559680,NULL,1,0,'17722254654','selected');
