INSERT INTO "feedback_replies" ("id","feedback_id","reply_type","content","admin_id","created_at","request_key") VALUES('0e349888-f28f-41f5-b1a7-543bf94b85fa','8932f3b2-d103-45a1-a963-4a0ba1d12227','live','感谢鹏友，我们已经收到了你的反馈，在后面的工作中，我们会改善我们的工作流程，让专业人员参与到我们的设计研发流程中，将产品的宣传图和UI做得越来越好！','admin-zd',1788965370311,'d0b7c2bb-535d-4cb1-a892-acd88b7b16fe');
INSERT INTO "feedback_replies" ("id","feedback_id","reply_type","content","admin_id","created_at","request_key") VALUES('2fe29066-8425-45d9-9d68-2db79d823046','674c6f97-69f6-46d2-9426-1d7df404c496','live',replace('鹏友你好，感谢你的反馈。铝合金壳体属于被动散热产品，作用是将内部的热量传导到壳体表面，帮助模块进行散热，因此外壳表面40～50度属于正常工作问题，鹏友不必担心，可以继续正常使用。\n同时要提醒鹏友的是，不要太过追求低温，温度过低可能会导致机器硬件出现无法联网的情况。','\n',char(10)),'admin-zd',1788965534074,'10e2791b-3b96-4694-a31d-4189434f4d56');
INSERT INTO "feedback_replies" ("id","feedback_id","reply_type","content","admin_id","created_at","request_key") VALUES('3e1c6db3-259c-4750-801e-750b7c5aec1a','47c4c3e6-437d-4859-a12b-049b0bbe3bcd','live','朋友您好，感谢您的反馈，您的问题可能是由于夜间运营商关闭基站导致的。您可以尝试在白天和夜间将机器后台状态截图，查看您的内置卡所连基站的信息，将截图反馈给困鹏团队，我们团队会帮你去判断问题究竟在哪里。','admin-zd',1788966556333,'06b6844e-66e1-4acd-9661-366661082315');
INSERT INTO "feedback_replies" ("id","feedback_id","reply_type","content","admin_id","created_at","request_key") VALUES('41777b77-40ef-4931-af8d-18a3c7ce8e99','c021b795-d060-4789-ad91-21934e335370','live','鹏友您好，感谢你的反馈。我们将我们的软件加速适配到不同产品，我们团队的相关成员一定会让您尽快用上功能完整结构美观的app，请您静候我们的佳音。','admin-zd',1788966723513,'f2dc81b0-3e33-4a55-8a23-c064e0f770c8');
