INSERT INTO "feedback_replies" ("id","feedback_id","reply_type","content","admin_id","created_at","request_key") VALUES('27b2f722-e237-42aa-ba4c-1d713c2657aa','793a71ee-4e47-4a5b-adc6-2803ef76e141','live',replace('鹏友您好，感谢您的反馈。我们建议您可以使用一台中继或者AP，对您的CPE信号进行增强，之前塑胶壳可以实现或许是因为角度原因，我们目前是不建议您使用一台设备为五层楼房提供网络服务的。\n后续可以关注我们的小店，我们也会推出能够提供中继服务的硬件设备。','\n',char(10)),'admin-zd',1788967561087,'d44deb3c-1b6d-429a-8b34-2b7de901d856');
INSERT INTO "feedback_replies" ("id","feedback_id","reply_type","content","admin_id","created_at","request_key") VALUES('21ee2a14-1338-44b7-9df9-613336fc6f55','796e7ba6-6198-44e5-9606-db2792cb810f','live',replace('鹏友您好，感谢您的反馈，我们会立刻解决您所反馈的已读不回的问题。\n您所反馈的清锋卡无法更换设备的原因，是由于目前运营商需要我们提供tac码和iccid一对一的绑定的信息，运营商才能够提供服务。青锋卡所绑定的max和ultra，已经给运营商进行了报备，因此可以使用。而pro由于模块报备方案比较复杂，比较难以解决，因此青锋卡不能再pro上面使用。\n您可以联系我们团队的小助理，将您的设备寄回，我们可以给您写入专门的串码，让您能够成功使用相关的流量卡服务。','\n',char(10)),'admin-zd',1788968806897,'9adfb60d-bfbf-4fa9-b050-0b398fa1cdb4');
