INSERT INTO "live_import_rows" ("job_id","row_number","nickname","content","status","attempt_token","lease_until","attempts","error_code","topic","custom_topic","routing_status") VALUES('37272b68-5dfa-4eaf-aa2a-500d2bacd5a1',49,'我真的很需要啊',replace('张导太厉害了，鲲鹏太牛了。其他人宣传天花乱坠的好卡放在手机里一般般，勉强够用，但是配上鲲鹏cpe，直接给杂卡榨干所有能力了，鲲鹏cpe的性能太猛了，他们口中的好卡也不过如此。鲲鹏的卡不一样，每一种卡配合鲲鹏的设备，在同等级别根本没有对手，跨级别也游刃有余，不仅设备强，种类还多，每个领域都是神的存在，我甚至感觉鲲鹏都可以收购华为！\n高中的时候身为一位体育生兼游戏爱好者，特别喜欢改造自己电竞屋，总是因为WiFi在客厅，网络不是那么好而发愁，到了大学，学校的网简直没法用，晚上高峰时期。甚至能到个位数。在我第一次搜索解决办法的时候，认识到了鲲鹏，在我了解了几天了之后，直接下单了Max，当用起来了的时候我就震惊了，堪比宽带的速度让我非常震惊，用到现在都没有一点问题，我的舍友也一起使用。延迟低的恐怖，让我们惊叹连连，让他们也主动加入鲲鹏的粉丝圈。\n二六年，六月开始关注张导抖音，有时间就看您直播，收获了很多，cpe的各种不懂问题都明白了，应对突发事件应急方式，跟张导大气的性格，直播间里偶尔来一下高速列车。张导真的非常厉害幽默，在解决了我们生活难题的同时也解决了我们每天积攒的疲惫，在直播间里逗我们笑，互相陪伴，教我们处对象等等，不过这几天因为天火卡原因，张导跟团队一定非常辛苦，张导都顶着黑眼圈工作，喝完酒还陪兄弟们聊天，这几天\n一定要注意休息，我也非常想帮助您跟您的团队，但是我的领域可能帮不上啥，还会给您添麻烦，但是我会默默支持您，正如您所说，鲲鹏的卡，只是为了衬托出鲲鹏cpe的强大，在我最近使用了张导发过来的天火卡后，才应了那句话，没有更好的卡，只有最好的cpe，去他m的华为，去他m的中兴，鲲鹏才是最牛逼的。以后我会继续发鲲鹏实战的视频和帮助鲲鹏出售产品，在使用过程中积极向您汇报问题，希望也能用上自己出过功劳的cpe。\n爱你张导，鲲鹏牛逼。祝张导年入千万，鲲鹏轻松进去世界五百强！！','\n',char(10)),'imported',NULL,0,1,NULL,'released_hardware',NULL,'selected');
