INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('ec8a20d5-e6c7-4d61-9f64-1d6bdc6e25bb','00000000-0000-4000-8000-000000000007','public','cb0ce931-d444-4bca-b10f-4215e372261b','精灵','张导，从上次匆匆见过那之前素未谋面的ak08定向天线，对其留下了深刻映像，然后突然有别的事情错过具体讲解了，这次留言测试一下这个留言板，一方面想向您具体了解一下这个产品各方面情况包括但不限于参数，使用场景等，另一方面呢想问问这个产品现在到什么进度了准备定价多少？能增强信号到一个什么程度？还请张导不吝讲解一番。','unreleased_product',NULL,1788587060628,0,75,1789109465405,'admin-ceshi',NULL,NULL,NULL,NULL,58);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('66bab1de-5dcb-4e42-9065-100a2c10728a','00000000-0000-4000-8000-000000000007','public','73f4a6d0-77c3-4fcf-8496-932efd382d2a','天使猪猪乐','为什么张导的店小程序有些东西需要特定会员购买，之前有c2000max原装拆机壳购买不了，而群里有些人就能购买。c2000max内测用户好久没关注过这方面了，只知道以前都是在鹏友go小程序上购买产品','other','张导的店特殊会员问题',1788604231724,0,2,1789109539414,'admin-ceshi',NULL,NULL,1789115572434,'admin-ceshi',0);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('6239aad9-8f5f-459d-ae43-8e3f81916f43','00000000-0000-4000-8000-000000000007','public','b110ff6e-015b-4416-96e7-6c7c75526e71','天干物燥','张导，我已经买了两个max了，但是呢还是更加喜欢铝合金的外壳，但是不想要外置天线，您之前说过铝合金有两个版本一个内置天线一个外置天线，所以请问会不会考虑给不想要外置天线的鹏友出一个内置天线的铝合金','released_hardware',NULL,1789102874912,0,89,1789109668859,'admin-fa',NULL,NULL,NULL,NULL,72);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('df3a6131-d11b-4096-8ba3-3ca598f4e988','00000000-0000-4000-8000-000000000007','public','34243920-1421-476c-acfd-09eb057d5a94','苏白ms','c2000max定制的金属图标能否用自己提供的图片定制','released_software',NULL,1788618939766,0,77,1789109753420,'admin-ceshi',NULL,NULL,NULL,NULL,60);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('4773d450-51ee-47a9-aa6b-7835ba9232d7','00000000-0000-4000-8000-000000000007','public','df0bd855-2e4d-4b2d-9456-a13559299f03','开心每一天','你好张导，max铝合金版后盖引磁片非常容易脱落，和小助理沟通回复是只能（等），本人因使用环境需要经常设备与支架分离，导致机器后盖引磁片脱落，这个问题很让我苦恼，希望张导能给个大概具体时间，谢谢。','released_hardware',NULL,1789084872809,0,73,1789112846914,'admin-ceshi',NULL,NULL,NULL,NULL,56);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('f0663c32-3087-4cbf-bb99-e4fb53bcf8ea','00000000-0000-4000-8000-000000000007','public','c92e1d29-09f2-498b-96d3-889fd19cbd50','114514研究所—白教授',replace('张导 可以让技术带团队试试vue做web后台 可以让他们给你先出个demo 后台会很流畅的 在直播间也反馈了也有一些人共鸣 现在很多大厂近几年产量也都是vue做的 目前我能找到的缺点就是后台操作动画上 有些不舒服 生硬\n我是也是做互联网产品的，如果需要外部开发非常欢迎联系我，我也可以一起做','\n',char(10)),'released_software',NULL,1789048201664,0,88,1789113409475,'admin-ceshi',NULL,NULL,NULL,NULL,71);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('71aae4c6-d31b-4068-8247-380bfa40de1e','00000000-0000-4000-8000-000000000007','public','537aa8fa-9394-425d-b2ba-a94493575214','远山',replace('产品：鲲鹏 C2000 Max。\n流量卡：天火卡\n《王者荣耀》，少部分时间 50-60，大部分时间 60-80 的延迟，偶尔 80 以上。\n永劫无间手游，相对王者稍稍好一点。\n永劫无间端游，70 左右的延迟。\n穿越火线端游，也差不多。','\n',char(10)),'other','游戏延迟问题。',1789042027223,0,7,1789113720348,'admin-ceshi',NULL,NULL,1789115738511,'admin-ceshi',0);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('11fa8101-5783-4074-92da-aad055af0280','00000000-0000-4000-8000-000000000007','public','27b2b53d-0640-4611-bbeb-6dc1a9772a87','超爱玩的熊猫',replace('①能不能依托鲲鹏软件或者网页建立一个鲲鹏佛山交流社区，根据鲲鹏不同的设备建立不同的分区，让鲲鹏每款设备的用户能即时交流，不用加各种群。同时能让鲲友在上面上传自己弄的固件，接过鲲鹏官方审核通过之后，放入官方固件页面。\n②既然鲲鹏C2000MAX的外壳能进行自定义图片，鲲鹏软件和网页的背景能不能自行更换自己喜欢的图片。','\n',char(10)),'other','鲲友交流、固件使用问题和网页/软件背景',1789040792812,0,80,1789113769727,'admin-ceshi',NULL,NULL,NULL,NULL,63);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('049f1709-3cda-4fe9-a3f4-4ecbe06c2065','00000000-0000-4000-8000-000000000007','public','b6325312-f0ed-4c2e-814e-a69bfb205b0d','咕咕','张导你好，我是妥妥的老粉，目前APP还是需要优化下，一是短信收不到还是，二是切换卡有时候还是太慢，三是查看基站点亮也是一直转圈圈，包括查看排行榜，四是导呀感觉说说MAX置换U的订单怎么下呀。迫不及待想换了，8月10才买的，目前长期出差一月在外地25天左右，想要AK08在小点，要便携的用，目前酒店WIFI不稳定还是想要后续U+AK08.哈哈我感觉这个得无敌了','released_software',NULL,1789040500654,0,9,1789113799298,'admin-ceshi',NULL,NULL,NULL,NULL,3);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('91c0c713-254d-4525-9185-309d70a7cf2a','00000000-0000-4000-8000-000000000007','public','e25537c2-1191-45ee-b1fe-9a055bdc94e2','🍂人情长౪ᩚᐝ异难还',replace('希望后继版本把限速改回来，\n不然2.2.15版本密码被人知道了联上就高速跑，几个小时没去看后台都不知道被人偷联了。\n原版的一开限速，新联上的设备要我们进去解限速的','\n',char(10)),'released_hardware',NULL,1789040037925,0,74,1789114228887,'admin-ceshi',NULL,NULL,NULL,NULL,57);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('56d2c951-88c7-4a67-9617-c887426f590c','00000000-0000-4000-8000-000000000007','public','2f6e5cb4-f45c-4ca9-ad90-2c2f62f34a68','114514研究所—白教授','张导 在经销商买被骗了 实名了内置卡发现充值要找他们个人微信充值 300g的套餐价格比官方1000g的贵 求申冤换卡 学生摊点小便宜结果被坑😭😭😭','appeal',NULL,1789040022936,0,11,1789114242657,'admin-ceshi',NULL,NULL,1789116710147,'admin-ceshi',0);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('39d2fa5b-53cc-4a18-80d6-3879d29519f9','00000000-0000-4000-8000-000000000007','public','54facdcd-8f50-4671-a821-430b41cf9844','🐴到成功',replace('张导，我是在校生，我想用Codex开发插件，但是在国内需要科学上网才能用Codex，现在国家对于科学上网这方面的管控到底是什么样子的，会不会被网警找上门😁\nOP系统后续会不会出使用教程（我是小白）','\n',char(10)),'other','关于科学上网和OP系统相关问题',1789031234673,0,12,1789114416399,'admin-ceshi',NULL,NULL,NULL,NULL,1);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('915d7a3a-3161-4d6c-8de7-346c0e4ef56c','00000000-0000-4000-8000-000000000007','public','ce603695-a493-4c5a-8bc0-e8b17a50ebe4','巴卫','鲲鹏的东西还不错，支持✊','released_hardware',NULL,1789014195208,0,13,1789114427383,'admin-ceshi',NULL,NULL,NULL,NULL,2);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('ed8404fb-96b9-4770-9582-09034bac107f','00000000-0000-4000-8000-000000000007','public','86bdb8b9-6812-40dc-881b-ac8d1cb079eb','毒刺',replace('始于体验，忠于匠心｜我的鲲鹏C2000MAX、NB CPE全程成长之旅\n \n从年前有幸参与鲲鹏C2000MAX公测开始，我便与鲲鹏设备结下了不解之缘。这段一路走来的使用历程，不只是一台上网设备的更迭升级，更是我亲眼见证品牌用心打磨产品、真诚对待用户、极致深耕服务的全过程。\n \n最初，我以公测用户的身份率先体验鲲鹏C2000MAX。带着好奇与期待深度实测使用，感受着新品的性能优势，同时也如实反馈使用中的细节问题。体验过后，出于对产品实力的认可，我果断入手了鲲鹏NB CPE设备，一步步深耕5G无线设备的使用与实测，沉浸式感受品牌的产品实力。\n \n为了追求更极致的网络体验，我不断搭配专属配件优化设备。从升级铝合金散热壳体、外置高增益天线，大幅提升设备散热效率与信号接收稳定性，解决了传统设备高温降频、信号偏弱的痛点；再到搭配天火流量卡，适配全网频段、优化网络速率，解锁了更流畅、低延迟的上网体验。每一次硬件升级，都是为了贴合真实使用场景，追求稳定高效的网络体验。\n \n而最让我惊喜与动容的，从来不止是产品的硬件实力，更是鲲鹏以人为本的温度与态度。使用过程中，难免会有体验不佳、心绪烦躁的时刻，张导始终耐心倾听、温柔劝导，细心解答我的所有疑问，安抚负面情绪，让冰冷的数码设备，多了一份难得的真诚与温暖。\n \n不同于多数品牌忽视用户反馈、迭代敷衍的现状，鲲鹏始终把用户体验放在首位。对于我以及众多用户提出的每一条建议、每一处问题反馈，官方都做到及时接收、快速响应、落地整改，从不敷衍搪塞。一次次软件迭代更新，一次次功能细节优化，从后台系统流畅度、频段适配优化，到使用细节、功能适配的打磨，始终精益求精。\n \n从最初的公测样机，到成熟的量产设备，从硬件配件的不断完善，再到如今专属UV个性定制壳体的上线，鲲鹏一直在突破自我、持续精进。硬件上不断打磨工艺、升级配置，力求把产品硬件做到极致；软件上持续迭代优化、修复短板，力求把系统体验做到极致；服务上真诚相待、耐心负责，力求把用户服务做到极致。\n \n一路走来，我亲眼见证一台设备从青涩到成熟，一个品牌从用心到深耕。不辜负每一份用户信任，不忽视每一处细节瑕疵，不敷衍每一次体验反馈。以匠心打磨产品，以真心守护用户，以极致诠释专业，这便是鲲鹏最动人的底气，也是我一路追随、始终认可的根本原因。','\n',char(10)),'other','我与鲲鹏风雨同舟',1788950851018,0,14,1789114445313,'admin-ceshi',NULL,NULL,NULL,NULL,4);
