INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('c96f77dc-48f8-4160-a699-ff1cf31ba87e','00000000-0000-4000-8000-000000000007','public','23e38ae0-c247-4237-a5df-1ea961233aec','星辰','我爱张导🥰，渴望每天醒来的第一眼看到的都是你。','other','爱上张导',1788842414085,0,18,1789114504023,'admin-ceshi',NULL,NULL,NULL,NULL,6);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('51aa7be8-45e8-4c0c-a856-6d7c8c84596a','00000000-0000-4000-8000-000000000007','public','7bc02f7a-b7bd-4fcf-9cc6-997168d27c53','Jz',replace('张导张导，认真反馈一个我觉得很重要也必须解决的问题——鲲鹏无限现在的Web后台和APP在整体产品质感尤其是视觉设计上还有很大的提升空间。\n\n我觉得鲲鹏做CPE最有潜力的一点，就是鲲鹏不只是一个简简单单的组装厂，把一堆的模组装进一个盒子里然后卖给用户，而是能把硬件性能，外观设计和系统体验等等汇聚成一个成熟而完美的产品体验。\n\n现在AI辅助开发已经非常成熟，前端实现的门槛快速降低，我觉得鲲鹏非常应该把审美、交互、细节重视起来，比方说Web和APP后台的信息层级、状态展示、图表等等，都应该认真的优化。\n\n我甚至有个很强烈的想法——鲲鹏应该成为，也完全可以成为CPE界的Apple。参数信号好这是基础，还要让用户第一次打开包装第一次看到设备第一次进入后台的时候，都能感觉到这个东西做得太美丽了。\n\n我自己是数据科学专业的学生，也一直在学习和使用AI、编程以及各种开发工具，对产品设计和前端也特别感兴趣，看到鲲鹏现在的软件界面，我是真的很想自己动手重新设计一套哈哈哈哈哈。\n\n如果鲲鹏愿意着手做UI改版和前端设计优化，我特别希望能参与进去，哪怕先让我做一个页面原型、改版Demo，或者帮忙提一整套交互和视觉方案都可以。\n\n我是真的挺希望看到鲲鹏把硬件、工业设计和软件体验全部做到同一个水准的。期待有一天“CPE界的Apple”真的就是鲲鹏。\n\n张导加油，鲲鹏加油！','\n',char(10)),'released_software',NULL,1788792006107,0,19,1789114557080,'admin-ceshi',NULL,NULL,NULL,NULL,7);
