INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('3eed0793-e5ce-4c7e-ba7b-7d5519c40f27','00000000-0000-4000-8000-000000000007','imported',NULL,'匿名鹏友','粉丝针对cpe的建议：桶装家庭款维持不变；方形 C2000 想去掉散热器，尾部加装通电就自动运转的风扇；外壳加厚，做两个孔位用螺丝旋转的方式实现设备固定，不确定这个方案是否可行；另外想做专用适配背包，设备放进去后背包对应风扇、天线位置预留开口。','unreleased_product',NULL,1789111714896,42,81,1789127406343,'admin-ceshi','37272b68-5dfa-4eaf-aa2a-500d2bacd5a1',42,NULL,NULL,64);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('d573ac52-3952-447e-8e9e-b9e7345efbe2','00000000-0000-4000-8000-000000000007','public','e6367913-99a1-4945-b374-327d3917307c','团',replace('张导你好，我大学的时候就接触到这类产品，当时生活费有限，一直是自己DIY玩，也因此了解到了鲲鹏和张导。\n深入了解后特别认可鲲鹏这个年轻品牌的产品，一直想入手官方的设备，但我自己已经有模块了，就想买无模块的空机。\n咱们现在有AK68的无模块版我知道，但它定位比较极致，像我这种普通市区用的用户其实用不上这么高的规格。\n特别希望张导能考虑上架C8-788这类更便携的无模块版本，给我们已有模块的玩家多一个亲民便携的选择。\n感谢张导能看到这里！','\n',char(10)),'other','希望增加便携款无模块设备的产品',1788801771499,0,60,1789122246675,'admin-ceshi',NULL,NULL,NULL,NULL,43);
