INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('f7e17b26-9530-4c6a-89af-7efca6e0dfc0','00000000-0000-4000-8000-000000000007','public','a8065806-7172-4c60-82ea-db653f0b1290','🐴到成功','AK08天线大概什么时候可以购买，现在我真的非常需要这个天线，我们校区今年多招收了559个人，导致这几天网速哐哐往下掉，无论白天还是晚上网速都拉不起来，就连天火卡也只有100兆的网速，之前移动卡都是260兆的网速，联通卡由原来的400兆掉到190兆，最主要的是无论哪个运营商的基站，玩网游时不时抽风，延迟突然飚到700毫秒，有了AK08天线我打算不用宿舍楼内的RRU了，直接用AK08天线对准远处校外的基站，校外的基站支持5G-A和三载波，请张导给个大概的时间，以平复我焦急等待的心，🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻🫰🏻','unreleased_product',NULL,1788782998891,0,70,1789125008176,'admin-ceshi',NULL,NULL,NULL,NULL,53);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('6d733153-20e1-4f80-8449-43e98adf58e5','00000000-0000-4000-8000-000000000007','public','e327540a-8cc4-447e-bc7d-446fd1f1a059','老樊','张导，max的游戏延迟还是稍微有点高，我之前使用过烽火的air和pro2代，在相同的位置下，烽火的产品游戏延迟要比max低个差不多10ms，而且游戏延迟波动也有点高，能差不多有5到8ms，我认为这不是硬件方面的问题，这应该是固件优化方面的，愿意入手max的基本上都是年轻人，喜欢玩些竞技类的游戏，对游戏延迟和波动还是比较在意的。在好点的基站下max的延迟确实能干到20ms以内，但是友商的产品也能做到，在不那么优秀的基站和信号下把游戏延迟和波动干低那才是真的牛逼，并不是所有用户周围的信号都很优秀，我认为一个优秀的产品不是仅仅是靠产品堆料给推上去的，后面的软件优化和使用体验才是最重要的，去年我也用过中兴的u60，这款产品的堆料确实很足，但他的软件优化真的是一言难尽，导，我作为m鲲鹏产品的用户，希望鲲鹏越来越好，也希望自己手里的max越来越完美。','other','游戏延迟',1788693276109,0,71,1789125073870,'admin-ceshi',NULL,NULL,NULL,NULL,54);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('5690cf30-a36d-4dae-af50-d32c232a6608','00000000-0000-4000-8000-000000000007','public','d79b5c62-d3c5-4556-bb95-deb697283dca','东北亚旅行家雪菜','max的WIFI7，可以增设mlo功能开关吗，还有就是可以新增一个信道优化功能。','released_hardware',NULL,1788960068446,0,72,1789125109605,'admin-ceshi',NULL,NULL,NULL,NULL,55);
