INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('ea84346d-4e2b-4a57-905b-1dda17fd8dc7','00000000-0000-4000-8000-000000000007','public','f6cec3ee-fb51-47a3-a6f8-0810e583cc94','天使猪猪乐','如果app和网页端只能二选一的话，个人更希望那些功能加在web端后台（技术上如果能实现的话），因为app也不是每个人都会去下载，但是网页端是每个用户都会登进去访问的','other','继上一条反馈问题',1788605193935,0,78,1789127312624,'admin-ceshi',NULL,NULL,NULL,NULL,61);
