INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('224a7ff4-982e-45da-834d-f62fd86d306f','00000000-0000-4000-8000-000000000007','public','128eeb6d-122d-41cd-a265-da974c0352b2','🔥🔥🔥🔥🔥🔥🔥🔥🔥🔥','天火卡算硬件嘛～我也不清楚，但是我好像要呀，不知道什么时间能回归，我是这个月月初买的max，在学校寝室这个大环境用了4-5天了内置的移动卡很好用，不卡，但是速率还差点意思，咳咳咳','released_hardware',NULL,1788794666924,0,82,1789127443841,'admin-ceshi',NULL,NULL,NULL,NULL,65);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('90487f1d-1a65-435d-8b2f-cfb4e8c83a79','00000000-0000-4000-8000-000000000007','public','995e3515-a9d9-4f4f-b671-53972467b501','无无无','Ultra版本开发板，普通温度已达到88度，只有铝合金，没有风扇就是耍流氓，建议设计风扇外壳，通过主板的预留风扇接口来使用风冷散热，改善热，只需更换外壳即可，不需要改散热，使用原装外壳即可，给更多的玩法，提高设备的使用寿命。','unreleased_product',NULL,1788833411659,0,83,1789127467433,'admin-ceshi',NULL,NULL,NULL,NULL,66);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('48a615d8-e6cd-411d-80a8-6c16ab761a54','00000000-0000-4000-8000-000000000007','public','60725963-398e-4bff-a53c-7ea55165f497','WBaKn','c2000max后台能不能更新屏蔽小区的功能，同样是n41频段，一个信号较好但是不能载波聚合，一个信号稍弱一点但是可以载波聚合，网速更快，但是CPE经常自动连上那个无载波聚合的基站，且锁小区后就无法载波聚合了。希望增加屏蔽小区的功能让CPE自动连上那个可以载波聚合的基站','released_software',NULL,1788945117590,0,90,1789127551070,'admin-ceshi',NULL,NULL,NULL,NULL,73);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('adbaf844-eca7-4baf-99cf-9035b3669083','00000000-0000-4000-8000-000000000007','public','87c66cb5-5fbe-41e3-9855-1cff1916c8b3','兔9号','张导798用户。，能不能手提架跟那个铝合金支架做个配套，这样出去方便。😭😭😭，铝合金架手提箱能不能来个优惠价？买了798，在吃土了😭😭😭。','released_hardware',NULL,1788934105504,0,91,1789127586369,'admin-ceshi',NULL,NULL,NULL,NULL,74);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('62c3b70a-83ac-4709-ad7a-abd7fa484698','00000000-0000-4000-8000-000000000007','public','4c243e3b-e67e-4700-ab40-0fbebba31318','锦禧褔食品（揭阳）',replace('鲲鹏未来发展展望\n1，坚持发展个性化diycpe美化工艺争取破圈\n​2.研究竞品某cpe游戏延迟，持续优化鲲鹏设备的游戏延迟，降低延迟，超过友商或者和友商齐平\n​3 软件持续优化聚合方面的bug，打通目前现有产品聚合便利性，既然鹏友要玩官方就出手优化\n​4.针对大众市场需求推出相应的产品，鲲鹏要赚钱别不好意思，随身WiFi什么的通通推陈出新，鲲鹏需要的是培养各种需要物联网上网的潜在鲲鹏用户，在鲲鹏这里既可以傻瓜式的上网也可以根据自己的喜好玩机\n​5.流量卡优化与运营商的合作，机卡绑定，让消费者只要入手鲲鹏设备就不为后续流量上网而担忧\n6，优化鲲鹏二手商城回收机制，让购买鲲鹏产品的鹏友没有后顾之忧，推出更明白易懂的置换政策\n7.时不时户外直播，毕竟办公室直播久了也会视觉疲劳\n\n还有很多很多的想法，这是我作为10+12级老粉的建议和想法，希望鲲鹏越来越好\n​','\n',char(10)),'other','建议',1789213135738,0,92,1789223559680,'admin-ceshi',NULL,NULL,NULL,NULL,75);
INSERT INTO "live_entries" ("id","batch_id","source_type","feedback_id","nickname","content","topic","custom_topic","source_created_at","import_order","queue_group","added_at","added_by","import_job_id","import_row_number","removed_at","removed_by","sort_order") VALUES('aeec1c94-2b8b-41a5-a4b4-63a92463921a','00000000-0000-4000-8000-000000000007','public','573e0197-f80f-46c1-8048-fb7ce89d400b','芭芭鸭鸭','近海测试本人真实船员三副＋渤海湾到长江口＋单航次航行3~4天锚泊2到15天 希望参与鲲鹏炮测试名额 为了网络焦头烂额 关注鲲鹏炮很久了一直没有出 希望能参与测试同时也希望能是最早一批购买者  测试结束后愿意邮寄回设备  希望张导考虑一下我','unreleased_product',NULL,1789208357761,0,93,1789223571029,'admin-ceshi',NULL,NULL,NULL,NULL,76);
