PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  phone_encrypted TEXT NOT NULL,
  phone_hash TEXT NOT NULL UNIQUE,
  douyin_nickname TEXT NOT NULL CHECK (length(trim(douyin_nickname)) BETWEEN 1 AND 40),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE otp_phone_state (
  phone_hash TEXT PRIMARY KEY,
  state TEXT NOT NULL CHECK (state IN ('sending', 'sent')),
  lease_token TEXT NOT NULL,
  lease_expires_at INTEGER NOT NULL,
  last_requested_at INTEGER NOT NULL,
  last_sent_at INTEGER,
  updated_at INTEGER NOT NULL
);
CREATE TABLE otp_challenges (
  id TEXT PRIMARY KEY,
  phone_hash TEXT NOT NULL,
  code_mac TEXT NOT NULL,
  nonce TEXT NOT NULL,
  sent_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count BETWEEN 0 AND 6),
  consumed_at INTEGER,
  invalidated_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE TABLE rate_limits (
  operation_key TEXT NOT NULL,
  window_started_at INTEGER NOT NULL,
  request_count INTEGER NOT NULL CHECK (request_count > 0),
  expires_at INTEGER NOT NULL,
  PRIMARY KEY (operation_key, window_started_at)
);
CREATE TABLE image_cleanup_queue (
  object_key TEXT PRIMARY KEY,
  not_before INTEGER NOT NULL,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  last_error TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE admins (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL UNIQUE COLLATE NOCASE
    CHECK (length(trim(username)) BETWEEN 1 AND 40),
  password_hash TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  last_login_at INTEGER
, must_change_password INTEGER NOT NULL DEFAULT 0);
CREATE TABLE admin_sessions (
  token_hash TEXT PRIMARY KEY,
  admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE,
  mode TEXT NOT NULL DEFAULT 'normal' CHECK (mode IN ('normal', 'live')),
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL CHECK (expires_at > created_at)
);
CREATE TABLE feedback (
  id TEXT PRIMARY KEY,
  submission_key TEXT NOT NULL UNIQUE,
  user_id TEXT REFERENCES users(id) ON DELETE RESTRICT,
  douyin_nickname TEXT NOT NULL
    CHECK (length(trim(douyin_nickname)) BETWEEN 1 AND 40),
  topic TEXT NOT NULL
    CHECK (topic IN ('released_hardware', 'released_software', 'unreleased_product', 'appeal', 'other')),
  custom_topic TEXT,
  content TEXT NOT NULL CHECK (length(trim(content)) BETWEEN 1 AND 2000),
  internal_status TEXT NOT NULL DEFAULT 'unprocessed'
    CHECK (internal_status IN ('unprocessed', 'pending_resolution', 'message_replied', 'livestream_replied')),
  reply_type TEXT CHECK (reply_type IN ('message', 'livestream')),
  reply_content TEXT,
  is_todo INTEGER NOT NULL DEFAULT 0 CHECK (is_todo IN (0, 1)),
  moderation_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (moderation_status IN ('pending', 'kept', 'filtered', 'failed')),
  moderation_source TEXT
    CHECK (moderation_source IN ('ai', 'manual')),
  moderation_category TEXT
    CHECK (moderation_category IN ('valid_feedback', 'abusive', 'meaningless', 'uncertain')),
  moderation_reason TEXT CHECK (moderation_reason IS NULL OR length(moderation_reason) <= 160),
  moderated_at INTEGER,
  privacy_policy_version TEXT NOT NULL,
  privacy_agreed_at INTEGER NOT NULL,
  livestream_policy_version TEXT NOT NULL,
  livestream_agreed_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL, moderation_attempt_token TEXT, moderation_attempts INTEGER NOT NULL DEFAULT 0, moderation_next_retry_at INTEGER NOT NULL DEFAULT 0, shop_phone TEXT DEFAULT NULL, routing_status TEXT NOT NULL DEFAULT 'pending'
  CHECK (routing_status IN ('pending', 'selected', 'not_selected')),
  CHECK (
    (topic = 'other' AND custom_topic IS NOT NULL AND length(trim(custom_topic)) BETWEEN 1 AND 60)
    OR (topic <> 'other' AND custom_topic IS NULL)
  ),
  CHECK (
    (internal_status IN ('unprocessed', 'pending_resolution') AND reply_type IS NULL AND reply_content IS NULL)
    OR (internal_status = 'message_replied' AND reply_type = 'message' AND reply_content IS NOT NULL AND length(trim(reply_content)) > 0)
    OR (internal_status = 'livestream_replied' AND reply_type = 'livestream' AND reply_content IS NOT NULL AND length(trim(reply_content)) > 0)
  )
);
CREATE TABLE feedback_images (
  id TEXT PRIMARY KEY,
  feedback_id TEXT NOT NULL REFERENCES feedback(id) ON DELETE CASCADE,
  object_key TEXT NOT NULL UNIQUE,
  media_type TEXT NOT NULL CHECK (media_type = 'image/webp'),
  byte_size INTEGER NOT NULL CHECK (byte_size > 0),
  width INTEGER NOT NULL CHECK (width BETWEEN 1 AND 8192),
  height INTEGER NOT NULL CHECK (height BETWEEN 1 AND 8192),
  sha256 TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE feedback_replies (
  id TEXT PRIMARY KEY,
  feedback_id TEXT NOT NULL REFERENCES feedback(id) ON DELETE CASCADE,
  reply_type TEXT NOT NULL CHECK (reply_type IN ('live', 'message')),
  content TEXT NOT NULL,
  admin_id TEXT REFERENCES admins(id) ON DELETE RESTRICT,
  created_at INTEGER NOT NULL, request_key TEXT,
  CHECK (
    (admin_id IS NULL AND length(trim(content)) > 0)
    OR (admin_id IS NOT NULL AND length(trim(content)) BETWEEN 1 AND 2000)
  )
);
CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE RESTRICT,
  feedback_id TEXT REFERENCES feedback(id) ON DELETE SET NULL,
  action TEXT NOT NULL CHECK (
    action IN (
      'reply_created',
      'todo_added',
      'todo_removed',
      'moderation_filtered',
      'moderation_restored'
    )
  ),
  created_at INTEGER NOT NULL
);
CREATE TABLE nickname_daily_limits (
  nickname TEXT NOT NULL,
  beijing_day TEXT NOT NULL,
  submission_count INTEGER NOT NULL CHECK (submission_count BETWEEN 1 AND 10),
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (nickname, beijing_day)
);
CREATE TABLE live_batches (
  id TEXT PRIMARY KEY,
  started_at INTEGER NOT NULL,
  archived_at INTEGER,
  archived_by TEXT REFERENCES admins(id),
  status TEXT NOT NULL CHECK (status IN ('active', 'archived')),
  playback_started_at INTEGER,
  next_queue_group INTEGER NOT NULL DEFAULT 0,
  revision INTEGER NOT NULL DEFAULT 0,
  successor_id TEXT UNIQUE,
  CHECK ((status = 'active' AND archived_at IS NULL AND archived_by IS NULL)
    OR (status = 'archived' AND archived_at IS NOT NULL AND archived_by IS NOT NULL))
);
CREATE TABLE live_import_jobs (
  id TEXT PRIMARY KEY,
  batch_id TEXT NOT NULL REFERENCES live_batches(id),
  file_hash TEXT NOT NULL,
  payload_hash TEXT NOT NULL,
  filename TEXT NOT NULL,
  file_size INTEGER NOT NULL CHECK (file_size BETWEEN 1 AND 2097152),
  row_count INTEGER NOT NULL CHECK (row_count BETWEEN 1 AND 500),
  created_by TEXT NOT NULL REFERENCES admins(id),
  created_at INTEGER NOT NULL,
  queue_group INTEGER NOT NULL DEFAULT 0,
  UNIQUE(batch_id, file_hash)
);
CREATE TABLE live_import_rows (
  job_id TEXT NOT NULL REFERENCES live_import_jobs(id),
  row_number INTEGER NOT NULL CHECK (row_number BETWEEN 2 AND 501),
  nickname TEXT NOT NULL CHECK (length(trim(nickname)) BETWEEN 1 AND 40),
  content TEXT NOT NULL CHECK (length(trim(content)) BETWEEN 1 AND 2000),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'failed', 'imported')),
  attempt_token TEXT,
  lease_until INTEGER NOT NULL DEFAULT 0,
  attempts INTEGER NOT NULL DEFAULT 0,
  error_code TEXT, topic TEXT
  CHECK (topic IN ('released_hardware', 'released_software', 'unreleased_product', 'appeal', 'other')), custom_topic TEXT, routing_status TEXT
  CHECK (routing_status IN ('pending', 'selected', 'not_selected')),
  PRIMARY KEY(job_id, row_number)
);
CREATE TABLE live_audit_logs (
  id TEXT PRIMARY KEY,
  request_key TEXT NOT NULL,
  admin_id TEXT NOT NULL REFERENCES admins(id),
  action TEXT NOT NULL CHECK (action IN ('routing_selected', 'routing_not_selected', 'live_removed', 'import_created', 'import_retried', 'batch_rotated')),
  batch_id TEXT NOT NULL REFERENCES live_batches(id),
  feedback_id TEXT REFERENCES feedback(id),
  target_id TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  UNIQUE(admin_id, request_key)
);
CREATE TABLE IF NOT EXISTS "live_entries" (
  id TEXT PRIMARY KEY,
  batch_id TEXT NOT NULL REFERENCES live_batches(id),
  source_type TEXT NOT NULL CHECK (source_type IN ('public', 'imported')),
  feedback_id TEXT REFERENCES feedback(id),
  nickname TEXT NOT NULL CHECK (length(trim(nickname)) BETWEEN 1 AND 40),
  content TEXT NOT NULL CHECK (length(trim(content)) BETWEEN 1 AND 2000),
  topic TEXT NOT NULL CHECK (topic IN ('released_hardware', 'released_software', 'unreleased_product', 'appeal', 'other')),
  custom_topic TEXT,
  source_created_at INTEGER NOT NULL,
  import_order INTEGER NOT NULL DEFAULT 0,
  queue_group INTEGER NOT NULL DEFAULT 0,
  added_at INTEGER NOT NULL,
  added_by TEXT NOT NULL REFERENCES admins(id),
  import_job_id TEXT,
  import_row_number INTEGER,
  removed_at INTEGER,
  removed_by TEXT REFERENCES admins(id), sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  UNIQUE(batch_id, feedback_id),
  UNIQUE(batch_id, import_job_id, import_row_number),
  FOREIGN KEY(import_job_id, import_row_number) REFERENCES live_import_rows(job_id, row_number),
  CHECK ((source_type = 'public' AND feedback_id IS NOT NULL AND import_job_id IS NULL AND import_row_number IS NULL)
    OR (source_type = 'imported' AND feedback_id IS NULL AND import_job_id IS NOT NULL AND import_row_number IS NOT NULL)),
  CHECK ((topic = 'other' AND custom_topic IS NOT NULL AND length(trim(custom_topic)) BETWEEN 1 AND 60 AND (source_type = 'public' OR trim(custom_topic) <> '其他'))
    OR (topic <> 'other' AND custom_topic IS NULL))
);
CREATE TABLE live_order_requests (
  id TEXT PRIMARY KEY,
  admin_id TEXT NOT NULL REFERENCES admins(id),
  request_key TEXT NOT NULL,
  batch_id TEXT NOT NULL REFERENCES live_batches(id) ON DELETE CASCADE,
  entry_id TEXT NOT NULL,
  position INTEGER NOT NULL CHECK (position > 0),
  expected_revision INTEGER NOT NULL CHECK (expected_revision >= 0),
  created_at INTEGER NOT NULL,
  UNIQUE(admin_id, request_key)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_otp_challenges_phone_sent ON otp_challenges(phone_hash, sent_at DESC);
CREATE INDEX idx_otp_challenges_expiry ON otp_challenges(expires_at);
CREATE INDEX idx_rate_limits_expiry ON rate_limits(expires_at);
CREATE INDEX idx_image_cleanup_due ON image_cleanup_queue(not_before, attempt_count);
CREATE INDEX idx_admin_sessions_admin ON admin_sessions(admin_id);
CREATE INDEX idx_admin_sessions_expiry ON admin_sessions(expires_at);
CREATE INDEX idx_feedback_created ON feedback(created_at DESC, id DESC);
CREATE INDEX idx_feedback_nickname_created ON feedback(douyin_nickname, created_at DESC, id DESC);
CREATE INDEX idx_feedback_moderation_created ON feedback(moderation_status, created_at DESC, id DESC);
CREATE INDEX idx_feedback_todo_created ON feedback(is_todo, moderation_status, created_at DESC, id DESC);
CREATE INDEX idx_feedback_receipt_number ON feedback(upper(substr(id, 1, 8)));
CREATE INDEX idx_feedback_images_feedback ON feedback_images(feedback_id);
CREATE INDEX idx_feedback_replies_feedback_created ON feedback_replies(feedback_id, created_at, id);
CREATE INDEX idx_feedback_replies_feedback_type ON feedback_replies(feedback_id, reply_type);
CREATE INDEX idx_feedback_replies_created ON feedback_replies(created_at, feedback_id);
CREATE INDEX idx_audit_logs_feedback_created ON audit_logs(feedback_id, created_at);
CREATE INDEX idx_nickname_daily_limits_updated ON nickname_daily_limits(updated_at);
CREATE UNIQUE INDEX idx_reply_request ON feedback_replies(admin_id, request_key);
CREATE INDEX idx_moderation_retry ON feedback(moderation_status, moderation_next_retry_at);
CREATE INDEX idx_feedback_routing ON feedback(moderation_status, routing_status, created_at, id);
CREATE UNIQUE INDEX idx_one_active_batch ON live_batches(status) WHERE status = 'active';
CREATE INDEX idx_live_import_work ON live_import_rows(status, lease_until);
CREATE INDEX idx_live_import_routing
  ON live_import_rows(status, routing_status, job_id, row_number);
CREATE INDEX idx_live_sequence ON live_entries(batch_id, removed_at, queue_group, source_created_at, import_order, id);
CREATE INDEX idx_live_custom_sequence ON live_entries(batch_id, removed_at, sort_order, queue_group, source_created_at, import_order, id);
CREATE TRIGGER live_entry_queue AFTER INSERT ON live_entries
BEGIN
  UPDATE live_batches SET revision = revision + 1 WHERE id = NEW.batch_id;
  UPDATE live_batches SET next_queue_group = next_queue_group + 1
    WHERE id = NEW.batch_id AND playback_started_at IS NOT NULL;
  UPDATE live_entries SET queue_group = CASE
    WHEN EXISTS (SELECT 1 FROM live_batches WHERE id = NEW.batch_id AND playback_started_at IS NOT NULL)
      THEN (SELECT next_queue_group FROM live_batches WHERE id = NEW.batch_id)
    ELSE 0 END
    WHERE id = NEW.id;
END;
CREATE TRIGGER live_entry_reselected AFTER UPDATE OF removed_at ON live_entries
WHEN OLD.removed_at IS NOT NULL AND NEW.removed_at IS NULL
  AND EXISTS (SELECT 1 FROM live_batches WHERE id = NEW.batch_id AND playback_started_at IS NOT NULL)
BEGIN
  UPDATE live_batches SET next_queue_group = next_queue_group + 1 WHERE id = NEW.batch_id;
  UPDATE live_entries SET queue_group = (SELECT next_queue_group FROM live_batches WHERE id = NEW.batch_id) WHERE id = NEW.id;
END;
CREATE TRIGGER live_membership_revision AFTER UPDATE OF removed_at ON live_entries
WHEN OLD.removed_at IS NOT NEW.removed_at
BEGIN
  UPDATE live_batches SET revision = revision + 1 WHERE id = NEW.batch_id;
END;
CREATE TRIGGER live_custom_order_insert AFTER INSERT ON live_entries
BEGIN
  UPDATE live_entries SET sort_order = COALESCE((
    SELECT MAX(sort_order) + 1 FROM live_entries
    WHERE batch_id = NEW.batch_id AND id <> NEW.id AND removed_at IS NULL AND sort_order > 0
  ), 0) WHERE id = NEW.id;
END;
CREATE TRIGGER live_custom_order_reselect AFTER UPDATE OF removed_at ON live_entries
WHEN OLD.removed_at IS NOT NULL AND NEW.removed_at IS NULL
BEGIN
  UPDATE live_entries SET sort_order = COALESCE((
    SELECT MAX(sort_order) + 1 FROM live_entries
    WHERE batch_id = NEW.batch_id AND id <> NEW.id AND removed_at IS NULL AND sort_order > 0
  ), 0) WHERE id = NEW.id;
END;
